package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.DcrAllowedGrantTypesVO;

class DcrAllowedGrantTypesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of dcr allowed grant types of tenant config")
  void test_dcr_allowed_grant_types_value_holder_assign_plain_value() {
    Object holder = new Object();
    DcrAllowedGrantTypesValueHolder<Object> value = new DcrAllowedGrantTypesValueHolder<>(holder);
    Assertions.assertSame(holder, value.dcrAllowedGrantTypes("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDcrAllowedGrantTypesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getDcrAllowedGrantTypes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.dcrAllowedGrantTypesNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getDcrAllowedGrantTypesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDcrAllowedGrantTypes().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of dcr allowed grant types of tenant config")
  void test_dcr_allowed_grant_types_value_holder_assign_value_object() {
    Object holder = new Object();
    DcrAllowedGrantTypesValueHolder<Object> value = new DcrAllowedGrantTypesValueHolder<>(holder);
    DcrAllowedGrantTypesVO vo = DcrAllowedGrantTypesVO.from("one");
    Assertions.assertFalse(value.getDcrAllowedGrantTypesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.dcrAllowedGrantTypes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDcrAllowedGrantTypesValue().orElseThrow());
    Assertions.assertSame(holder, value.dcrAllowedGrantTypes(Optional.empty()));
    Assertions.assertFalse(value.getDcrAllowedGrantTypesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.dcrAllowedGrantTypes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDcrAllowedGrantTypesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of dcr allowed grant types of tenant config against the original")
  void test_dcr_allowed_grant_types_value_holder_read() {
    Object holder = new Object();
    DcrAllowedGrantTypesValueHolder<Object> value = new DcrAllowedGrantTypesValueHolder<>(holder);
    DcrAllowedGrantTypesVO vo = DcrAllowedGrantTypesVO.from("one");
    DcrAllowedGrantTypesVO other = DcrAllowedGrantTypesVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getDcrAllowedGrantTypesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDcrAllowedGrantTypes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDcrAllowedGrantTypes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.dcrAllowedGrantTypes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDcrAllowedGrantTypes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDcrAllowedGrantTypes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of dcr allowed grant types of tenant config")
  void test_dcr_allowed_grant_types_value_holder_unset() {
    Object holder = new Object();
    DcrAllowedGrantTypesValueHolder<Object> value = new DcrAllowedGrantTypesValueHolder<>(holder);
    DcrAllowedGrantTypesVO vo = DcrAllowedGrantTypesVO.from("one");
    value.dcrAllowedGrantTypes(vo);
    Assertions.assertSame(holder,
        value.unsetDcrAllowedGrantTypesIfMatches("dcrAllowedGrantTypes_other"));
    Assertions.assertTrue(value.getDcrAllowedGrantTypesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDcrAllowedGrantTypesIfMatches("dcrAllowedGrantTypes"));
    Assertions.assertFalse(value.getDcrAllowedGrantTypesValue().isPresent(),
        "The field name must clear the value");
    value.dcrAllowedGrantTypes(vo);
    Assertions.assertSame(holder, value.unsetDcrAllowedGrantTypes());
    Assertions.assertFalse(value.getDcrAllowedGrantTypesValue().isPresent(),
        "Unset must clear the value");
  }
}
